SELECT 'contrato checks de canecas_secuencias (huella exacta)' AS verificacion, IF((SELECT COALESCE(MD5(GROUP_CONCAT(x ORDER BY BINARY x SEPARATOR '~~')), MD5('')) FROM (SELECT CONCAT_WS(0x1f, IFNULL(CAST(t.TABLE_NAME AS CHAR),'<NULL>'), IFNULL(CAST(t.CONSTRAINT_NAME AS CHAR),'<NULL>'), IFNULL(CAST(c.CHECK_CLAUSE AS CHAR),'<NULL>')) AS x FROM information_schema.TABLE_CONSTRAINTS t JOIN information_schema.CHECK_CONSTRAINTS c ON c.CONSTRAINT_SCHEMA=t.CONSTRAINT_SCHEMA AND c.TABLE_NAME=t.TABLE_NAME AND c.CONSTRAINT_NAME=t.CONSTRAINT_NAME WHERE t.CONSTRAINT_SCHEMA='u611730801_Plataforma' AND t.TABLE_NAME='canecas_secuencias') h)='e2815b62f1cda34327e83599e37ae2e7', 'OK', 'DETENER') AS resultado;
